void mainImage(out vec4 couleurFragment, in vec2 coordFragment) {
    float temps = iTime;
    float distanceRayon = fract(dot(coordFragment, sin(coordFragment)));

    couleurFragment = vec4(0.0);

    vec2 positionEcran = (coordFragment * 1.7 - iResolution.xy) / iResolution.y;
    positionEcran *= 1.5 + dot(positionEcran, positionEcran) * (0.3 + 0.2 * sin(temps * 3.0));

    float angleA = temps * 0.07;
    float angleB = sin(temps * 0.2) * 0.6;

    vec3 origineRayon = vec3(sin(angleA) * cos(angleB), sin(angleB), cos(angleA) * cos(angleB)) * 3.0;
    vec3 pointCible = vec3(sin(temps * 0.5), cos(temps * 0.4), 0.0) * 0.3;
    vec3 directionRegard = normalize(pointCible - origineRayon);

    vec3 axeHorizontal = normalize(vec3(-directionRegard.z, 0.0, directionRegard.x));
    vec3 axeVertical = normalize(cross(axeHorizontal, directionRegard));
    vec3 directionRayon = normalize(positionEcran.x * axeHorizontal + positionEcran.y * axeVertical + 1.0 * directionRegard);

    for(int i = 0; i < 100; i++) {
        vec3 positionEspace = origineRayon + distanceRayon * directionRayon;
        positionEspace.xz = mod(positionEspace.xz + 2.0, 4.0) - 2.0;

        float echelleFractale = 1.2;

        for(int j = 0; j < 4; j++) {
            positionEspace = abs(positionEspace) - vec3(0.1, 0.4, 0.1);
            float facteurInversion = max(0.2 / dot(positionEspace, positionEspace), 0.3);

            echelleFractale *= facteurInversion;
            positionEspace *= facteurInversion;

            positionEspace.xy = vec2(positionEspace.x - positionEspace.y * sin(0.2), positionEspace.x * sin(0.5) + positionEspace.y * cos(0.7));
            positionEspace.yz = vec2(positionEspace.y - positionEspace.z * sin(0.3), positionEspace.z * cos(0.02));
        }

        float distanceProche = length(positionEspace) / echelleFractale;

        couleurFragment += (sin(distanceRayon * 0.8 - temps * 4.0) * 0.5 + 0.5) / distanceProche / 300.0;
        distanceRayon += distanceProche * 0.3;
    }

    couleurFragment = tanh(couleurFragment / 4.0);
    couleurFragment.rgb = pow(couleurFragment.rrr, vec3(1.0));
}
